create or replace function public.set_datasub_provider_automatic_routing(p_provider_id uuid,p_enabled boolean,p_minimum_balance numeric default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare p public.datasub_providers%rowtype; m jsonb; begin if not (private.is_admin(auth.uid()) or private.has_product_access(auth.uid(),'datasub','manage')) then raise exception 'Permission denied'; end if; select * into p from public.datasub_providers where id=p_provider_id for update; if p.id is null then raise exception 'Provider not found'; end if; m=coalesce(p.metadata,'{}'::jsonb)||jsonb_build_object('manual_enabled',p_enabled); if p_minimum_balance is not null then m=m||jsonb_build_object('minimum_balance',greatest(0,p_minimum_balance)); end if; update public.datasub_providers set metadata=m,is_active=case when not p_enabled then false else is_active end,updated_at=now() where id=p.id; return jsonb_build_object('provider_id',p.id,'automatic_routing_enabled',p_enabled,'minimum_balance',coalesce((m->>'minimum_balance')::numeric,0)); end $$; revoke all on function public.set_datasub_provider_automatic_routing(uuid,boolean,numeric) from public,anon; grant execute on function public.set_datasub_provider_automatic_routing(uuid,boolean,numeric) to authenticated;